            family = "Insulina + GLP-1",
            aliases = listOf("glargina lixisenatida", "lixisenatida glargina"),
            summary = "Esta combinación contiene insulina glargina y lixisenatida en una pluma de proporción fija; no es glargina sola.",
            identify = "La glargina es una insulina basal de acción prolongada. La lixisenatida pertenece a los agonistas del receptor GLP-1, medicamentos que actúan sobre señales relacionadas con la respuesta del organismo a las comidas.\n\nEl envase contiene ambos componentes en proporción fija. No es glargina sola ni lixisenatida sola y tiene advertencias propias que deben revisarse con el equipo." ,
            purpose = "La ficha estadounidense describe su uso para mejorar el control de glucosa en adultos con diabetes tipo 2, junto con las medidas acordadas con el equipo. El profesional explica el papel de cada componente y el objetivo del producto en el plan.\n\nLa referencia no lo recomienda como tratamiento de cetoacidosis, una complicación que requiere atención médica. Leer esta ficha no determina si el producto es adecuado para una persona." ,
            mechanism = "La glargina ayuda a que los tejidos capten glucosa de la sangre y reduce su producción por el hígado durante un periodo prolongado. La lixisenatida actúa sobre el receptor GLP-1 y participa en respuestas relacionadas con insulina y glucagón tras las comidas; también retrasa el vaciamiento del estómago.\n\nLa combinación tiene una proporción fija: no es posible ajustar sus componentes independientemente con la misma pluma. No se deben deducir equivalencias con glargina sola u otro producto.",
            effects = "Pueden aparecer hipoglucemia, náusea o diarrea. Una baja de glucosa puede acompañarse de hambre, sudoración, temblor, mareo o confusión, aunque sus señales varían.\n\nLa pérdida de conciencia o las convulsiones requieren atención urgente. El dolor abdominal intenso y persistente puede acompañar una pancreatitis y necesita valoración médica; la dificultad para respirar o hinchazón de cara o garganta puede indicar alergia grave y requiere atención urgente. Vómitos o diarrea intensos pueden contribuir a pérdida de líquidos y afectar los riñones.",
            contra = "La ficha contraindica este producto durante episodios de hipoglucemia y ante reacción grave de hipersensibilidad a glargina, lixisenatida o sus componentes. Una contraindicación es distinta de una precaución que necesita valoración.",
            prec = "El equipo debe conocer enfermedades renales, molestias digestivas importantes, gastroparesia —vaciamiento lento del estómago— y antecedentes de pancreatitis. Comunica su uso antes de procedimientos con anestesia o sedación profunda: la ficha advierte que el vaciamiento más lento puede relacionarse con aspiración de contenido del estómago.\n\nPide instrucciones al equipo para enfermedad, una baja de glucosa o una administración olvidada. No suspendas ni ajustes el medicamento por cuenta propia.",
            inter = "Otros medicamentos para diabetes pueden aumentar el riesgo de hipoglucemia y algunos betabloqueadores ocultar señales. Como esta combinación retrasa el vaciamiento del estómago, puede afectar la absorción de algunos medicamentos orales.\n\nLa referencia no recomienda combinarla con otro producto que contenga un agonista GLP-1. El médico o farmacéutico debe revisar todos los envases y suplementos; esta lista no es completa y no autoriza modificar tratamientos." ,
            forms = "La fuente describe una pluma subcutánea de uso individual con dos componentes en proporción fija. No debe compartirse, aunque se cambie la aguja. La ficha no autoriza esta combinación en una bomba ni mezclarla con otras insulinas o soluciones.\n\nNo es una pluma de glargina sola ni equivale automáticamente a otras combinaciones; comprueba el nombre completo y pide formación sobre el dispositivo. No hagas conversiones por tu cuenta." ,
            consult = "¿Qué función cumple cada componente y cómo identificamos correctamente la pluma? ¿Qué señales de glucosa baja o molestias abdominales requieren atención? ¿Debemos revisar otros medicamentos orales o productos GLP-1? ¿Qué instrucciones pedimos antes de una cirugía o sedación?" ,
            sources = listOf(
                DrugReference("FDA", "SOLIQUA 100/33 · información para prescribir", "https://www.accessdata.fda.gov/drugsatfda_docs/label/2026/208673s023lbl.pdf", "Revisión 03/2026 · Reference ID 5761774", reviewedOn = "22 de noviembre de 2026"),
            ),
            relatedQuestions = listOf(
                DrugRelatedQuestion("¿Qué hace cada componente de esta pluma?", DrugIntent.MECHANISM),
                DrugRelatedQuestion("¿Por qué debemos revisar otros productos GLP-1?", DrugIntent.INTERACTIONS),
                DrugRelatedQuestion("¿Se puede utilizar esta combinación en una bomba?", DrugIntent.FORMULATIONS),
            ),
            related = listOf("insulin_glargine"),
        ),
        entry(
            id = "insulin_degludec_liraglutide",
            name = "Insulina degludec + liraglutida",
            family = "Insulina + GLP-1",
            aliases = listOf("degludec liraglutida", "liraglutida degludec"),
            summary = "Esta combinación contiene insulina degludec y liraglutida en una pluma de proporción fija; no es degludec sola.",
            identify = "Degludec es una insulina basal de acción prolongada. Liraglutida pertenece a los agonistas del receptor GLP-1, medicamentos que actúan sobre señales implicadas en la respuesta a las comidas.\n\nAmbos componentes se encuentran en el mismo dispositivo y en proporción fija. La combinación no es degludec sola ni liraglutida sola; identifica el nombre completo del envase." ,
            purpose = "La ficha estadounidense describe su uso para mejorar el control de glucosa en adultos con diabetes tipo 2, junto con las medidas acordadas con el equipo. No se recomienda para tratar una cetoacidosis. La lectura de esta ficha no decide qué tratamiento necesita una persona.",
            mechanism = "Degludec aporta insulina que ayuda a que los tejidos capten glucosa y reduce su producción por el hígado durante un periodo prolongado. Liraglutida actúa sobre el receptor GLP-1 e influye en señales relacionadas con insulina, glucagón y vaciamiento del estómago.\n\nLa proporción es fija en la pluma: no se pueden ajustar sus dos componentes por separado con el mismo envase. No se deben deducir equivalencias con degludec sola ni con otras combinaciones.",
            effects = "Se describen náusea, diarrea y dolor de cabeza; también puede producir hipoglucemia o glucosa baja. Las señales de una baja pueden incluir hambre, temblor, sudoración o confusión y no se manifiestan igual en todas las personas.\n\nLa pérdida de conciencia o convulsiones requieren atención urgente. El dolor abdominal intenso y persistente puede acompañar una pancreatitis y necesita valoración médica; la dificultad para respirar o hinchazón de cara o garganta pueden indicar alergia grave y requieren atención urgente. Los vómitos o diarrea intensos pueden contribuir a deshidratación y afectar los riñones.",
            contra = "La ficha contraindica este producto durante hipoglucemia, ante alergia grave a sus componentes y si existe antecedente personal o familiar de carcinoma medular de tiroides o neoplasia endocrina múltiple tipo 2.\n\nLa advertencia tiroidea procede de tumores observados en animales con liraglutida; la ficha aclara que se desconoce su relevancia en humanos. Es importante comunicar esos antecedentes al equipo sin inferir un diagnóstico.",
            prec = "El equipo debe conocer antecedentes de pancreatitis, función renal y gastroparesia, que es un vaciamiento lento del estómago. Comunica su uso antes de anestesia o sedación profunda: la ficha advierte que el vaciamiento más lento puede relacionarse con aspiración de contenido del estómago.\n\nPide instrucciones específicas ante enfermedad, una baja de glucosa o una administración olvidada; no suspendas ni ajustes el medicamento por tu cuenta.",
            inter = "Otros medicamentos para diabetes pueden aumentar el riesgo de hipoglucemia y algunos betabloqueadores ocultar señales. Como esta combinación retrasa el vaciamiento del estómago, puede afectar la absorción de ciertos medicamentos orales.\n\nLa referencia no recomienda combinarla con otro producto que contenga liraglutida u otro agonista GLP-1. La revisión profesional debe incluir todos los productos utilizados; no cambies el plan por tu cuenta." ,
            forms = "La fuente describe una pluma subcutánea de uso individual con dos componentes. No debe compartirse, aunque se cambie la aguja; el equipo debe enseñar a reconocer y utilizar el dispositivo indicado.\n\nNo es degludec sola y sus contraindicaciones no son idénticas a las de glargina/lixisenatida. Comprueba el nombre completo y no deduzcas equivalencias o conversiones entre productos." ,
            consult = "¿Qué función cumple cada componente y cómo identificamos la pluma? ¿Qué antecedentes tiroideos o pancreáticos debemos comunicar? ¿Qué señales de glucosa baja o molestias abdominales requieren atención? ¿Debemos revisar otros productos GLP-1 y qué instrucciones pedimos antes de anestesia?" ,
            sources = listOf(
                DrugReference("NLM · DailyMed", "XULTOPHY 100/3.6 · ficha oficial", "https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=21335fe4-d395-4501-ac2a-2f20d7520da9", "Revisión 10/2025", reviewedOn = "22 de noviembre de 2026"),
            ),
