        entry(
            id = "metformin_sitagliptin",
            name = "Metformina + sitagliptina",
            family = "Combinaciones orales",
            aliases = listOf("sitagliptina metformina", "metformina sitagliptina"),
            summary = "Combinación de biguanida e inhibidor DPP-4 para diabetes tipo 2.",
            identify = "Esta tableta reúne metformina y sitagliptina, dos principios activos de familias diferentes. Una sola tableta puede contener ambos, por lo que no equivale a metformina sola ni a sitagliptina sola." ,
            purpose = "La ficha estadounidense describe esta combinación, junto con las medidas de alimentación y actividad física acordadas con el equipo, para mejorar el control de la glucosa en adultos con diabetes tipo 2. No permite decidir si es adecuada para una persona concreta.\n\nAl revisar una caja conviene identificar los dos componentes: otros productos también pueden contener metformina. El equipo o farmacéutico puede ayudar a revisar el conjunto de medicamentos indicados." ,
            mechanism = "El hígado produce y libera glucosa incluso entre comidas. La metformina reduce principalmente esa producción y también ayuda a que el cuerpo responda mejor a la insulina.\n\nDespués de comer, el intestino libera señales llamadas incretinas. La sitagliptina bloquea una enzima que las descompone, llamada DPP-4; así prolonga señales que ayudan al páncreas a regular la liberación de insulina y glucagón en relación con la glucosa. Son acciones diferentes dentro de una misma tableta." ,
            effects = "Pueden aparecer diarrea u otras molestias digestivas, dolor de cabeza y síntomas respiratorios altos. Comunica los síntomas que persisten o dificultan comer y beber; una molestia aislada no demuestra su causa.\n\nLa acidosis láctica es una complicación poco frecuente pero grave asociada a metformina. Somnolencia inusual, debilidad intensa o dificultad respiratoria requieren atención urgente. Dolor intenso y persistente en el abdomen, que puede extenderse hacia la espalda, también necesita valoración pronta porque puede relacionarse con inflamación del páncreas. La dificultad para respirar o la hinchazón de cara o garganta requiere atención urgente." ,
            contra = "Contraindicada en insuficiencia renal grave, acidosis metabólica y alergia grave a los componentes.",
            prec = "Los riñones participan en la eliminación de los componentes, por lo que el equipo revisa su función antes y durante el tratamiento. La edad avanzada, enfermedad hepática, pérdida de líquidos y consumo excesivo de alcohol son circunstancias relevantes para el riesgo de acidosis láctica. El uso de metformina puede asociarse con disminución de vitamina B12.\n\nComunica antecedentes de pancreatitis o insuficiencia cardiaca. Antes de cirugía o un estudio con contraste, pide las instrucciones específicas al equipo; no suspendas ni reinicies el medicamento basándote en una regla genérica." ,
            inter = "La insulina y las sulfonilureas pueden aumentar el riesgo de hipoglucemia cuando se combinan con este producto. El alcohol en exceso y medicamentos como topiramato o los que reducen la eliminación de metformina requieren revisión por posibles riesgos.\n\nNo es una lista completa. Muestra al profesional todos los medicamentos, suplementos y productos sin receta; no cambies el tratamiento a partir de esta guía." ,
            forms = "La referencia corresponde a tabletas de liberación inmediata. Existen otros productos con liberación prolongada y sus instrucciones pueden ser diferentes. Comprueba el nombre, ambos principios activos y la presentación en el envase; compartir componentes no garantiza que las tabletas sean intercambiables." ,
            consult = "¿Qué aporta cada componente y cómo identifico mi presentación? ¿Cuándo se revisarán riñón y vitamina B12? ¿Qué síntomas digestivos o de dolor abdominal debo comunicar? ¿Qué instrucciones aplican si se programa un estudio con contraste o una cirugía?" ,
            sources = listOf(
                DrugReference("FDA", "JANUMET · información para prescribir", "https://www.accessdata.fda.gov/drugsatfda_docs/label/2026/022044s058lbl.pdf", "Revisión 08/2026 · Reference ID 5849549", reviewedOn = "22 de noviembre de 2026"),
            ),
            relatedQuestions = listOf(
                DrugRelatedQuestion("¿Cómo actúa cada componente de la combinación?", DrugIntent.MECHANISM),
                DrugRelatedQuestion("¿Por qué el equipo revisa los riñones y la vitamina B12?", DrugIntent.PRECAUTIONS),
                DrugRelatedQuestion("¿Qué distingue esta presentación de liberación inmediata?", DrugIntent.FORMULATIONS),
            ),
