        entry(
            id = "metformin_linagliptin",
            name = "Metformina + linagliptina",
            family = "Combinaciones orales",
            aliases = listOf("linagliptina metformina", "metformina linagliptina"),
            summary = "Combinación de biguanida e inhibidor DPP-4 en una tableta.",
            identify = "Esta tableta reúne metformina y linagliptina. Aunque los dos componentes ayudan a controlar la glucosa, pertenecen a familias distintas y ambos deben revisarse al identificar el medicamento." ,
            purpose = "La ficha estadounidense describe esta combinación de linagliptina y metformina para mejorar el control de glucosa en adultos con diabetes tipo 2, junto con las medidas de alimentación y actividad física acordadas con el equipo. Una tableta contiene dos principios activos; conviene identificarlos al revisar todos los envases con el profesional.\n\nLa ficha no recomienda este producto para diabetes tipo 1 y señala que no se ha estudiado en personas con antecedentes de pancreatitis. El equipo interpreta esos antecedentes y explica si la formulación corresponde al plan; esta información no decide un tratamiento individual ni acredita disponibilidad en México." ,
            mechanism = "El hígado produce glucosa aun cuando no estamos comiendo; la metformina ayuda principalmente a disminuir esa producción. Después de comer, el intestino libera señales llamadas incretinas, que participan en el control de insulina y glucagón.\n\nLa linagliptina bloquea DPP-4, una enzima que descompone esas señales. Así prolonga su efecto y ayuda al páncreas a regular ambas hormonas en relación con la glucosa. La combinación reúne estas acciones en una sola tableta." ,
            effects = "La ficha describe diarrea y nasofaringitis, es decir, molestias de nariz y garganta, entre las reacciones más frecuentes. Comunica al equipo los síntomas persistentes o que dificulten comer o beber; no todas las personas los presentan.\n\nLa acidosis láctica es una complicación poco frecuente pero grave asociada a metformina. Debilidad intensa, somnolencia inusual o dificultad respiratoria requieren atención urgente. Un dolor abdominal intenso y persistente puede ser una señal de inflamación del páncreas y necesita valoración pronta. La dificultad para respirar, hinchazón de cara o garganta y lesiones extensas con ampollas también requieren atención urgente." ,
            contra = "La etiqueta consultada contraindica esta combinación cuando existe función renal gravemente reducida, acidosis metabólica —incluida la cetoacidosis— o hipersensibilidad a alguno de sus ingredientes. Una contraindicación es distinta de una precaución: otras circunstancias pueden requerir valoración y seguimiento por el equipo.\n\nLa función renal se estima con análisis que un profesional debe interpretar; la aplicación no determina si una persona puede utilizar el medicamento.",
            prec = "La función renal es importante para valorar la seguridad de esta combinación por su componente de metformina. La edad avanzada, enfermedad hepática, pérdida de líquidos y consumo excesivo de alcohol pueden aumentar el riesgo de acidosis láctica. El uso de metformina también puede asociarse con niveles bajos de vitamina B12.\n\nComunica al equipo antecedentes de pancreatitis y cambios importantes de salud. Antes de cirugía o un estudio con contraste, solicita instrucciones específicas; no suspendas ni reinicies la tableta a partir de esta ficha." ,
            inter = "La rifampicina puede disminuir el efecto de linagliptina. El alcohol en exceso y algunos medicamentos que reducen la eliminación de metformina requieren valoración por el riesgo de acidosis láctica. Con insulina o sulfonilureas puede aumentar el riesgo de una bajada excesiva de glucosa.\n\nEstos son ejemplos de la ficha, no una lista completa. Lleva al equipo los nombres de los medicamentos y suplementos que utiliza la persona antes de introducir cambios." ,
            forms = "La referencia corresponde a tabletas de liberación inmediata. Otros productos con liberación prolongada tienen documentación e instrucciones propias. Revisa el nombre completo, ambos ingredientes y la presentación en el envase; no supongas equivalencia por compartir componentes." ,
            consult = "¿Qué aporta cada componente y cómo reconozco la presentación? ¿Cómo se revisarán la función renal y la vitamina B12? ¿Qué dolor abdominal o cambios en la piel debo comunicar? ¿Qué indicaciones nos darán antes de un estudio con contraste?" ,
            sources = listOf(
                DrugReference("NLM · DailyMed", "JENTADUETO · ficha oficial", "https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=f6dd9b86-0d18-95d4-2bc7-05591bfdd597", "Revisión 08/2026", reviewedOn = "22 de noviembre de 2026"),
            ),
            relatedQuestions = listOf(
                DrugRelatedQuestion("¿Cómo actúan metformina y linagliptina?", DrugIntent.MECHANISM),
                DrugRelatedQuestion("¿Por qué se revisa la función renal en esta combinación?", DrugIntent.PRECAUTIONS),
                DrugRelatedQuestion("¿Qué interacción se describe con rifampicina?", DrugIntent.INTERACTIONS),
            ),
            related = listOf("metformin_sitagliptin", "empagliflozin_linagliptin"),
        ),
        entry(
            id = "metformin_vildagliptin",
            name = "Metformina + vildagliptina",
            family = "Combinaciones orales",
            aliases = listOf("vildagliptina metformina", "metformina vildagliptina"),
            summary = "Combinación de biguanida y DPP-4 documentada en la Unión Europea.",
            identify = "La referencia europea describe tabletas que reúnen vildagliptina y metformina. Son dos principios activos de familias distintas; el producto no equivale a metformina sola." ,
            purpose = "La ficha europea contempla la combinación para mejorar el control de glucosa en adultos con diabetes tipo 2 en situaciones específicas, por ejemplo cuando la metformina sola no logra el control buscado o cuando ya se usan ambos componentes por separado. El equipo determina si corresponde a una persona y cómo realizar el seguimiento." ,
            mechanism = "El hígado produce glucosa incluso entre comidas. La metformina ayuda principalmente a disminuir esa producción. La vildagliptina bloquea una enzima llamada DPP-4 que descompone señales intestinales llamadas incretinas.\n\nAl prolongarse esas señales, ayudan al páncreas a regular la liberación de insulina y glucagón en relación con la glucosa. Ambos componentes actúan de forma diferente y tienen precauciones propias." ,
            effects = "Pueden aparecer náusea, diarrea o dolor de cabeza; no todas las personas las presentan. Comunica al equipo las molestias persistentes o que dificulten comer y beber.\n\nLa pancreatitis es inflamación del páncreas: un dolor abdominal intenso y persistente requiere valoración urgente. La piel u ojos amarillos pueden acompañar problemas del hígado. Debilidad intensa, somnolencia o dificultad para respirar requieren atención urgente por la posibilidad de acidosis láctica, una acumulación grave de ácido asociada a metformina. La aplicación no puede confirmar la causa de un síntoma." ,
            contra = "La ficha europea incluye alergia, acidosis, precoma diabético, insuficiencia renal grave, alteración hepática, lactancia, alcoholismo y enfermedades agudas con deshidratación, shock o falta de oxígeno; también contraste intravascular.",
            prec = "La ficha indica revisar la función renal y las pruebas del hígado antes y durante el tratamiento; en personas mayores la función renal puede requerir mayor vigilancia. El equipo también debe conocer antecedentes de pancreatitis o ciertos trastornos mitocondriales.\n\nInforma antes de una cirugía o estudio con contraste y pide instrucciones específicas. No suspendas ni reinicies el medicamento basándote en un plazo genérico de esta guía." ,
            inter = "Algunos medicamentos para la presión llamados IECA pueden aumentar el riesgo de angioedema, una hinchazón que puede afectar la cara o la garganta. Los antiinflamatorios y diuréticos pueden afectar la función renal; el alcohol en exceso aumenta el riesgo de acidosis láctica.\n\nOtros tratamientos para reducir glucosa pueden aumentar el riesgo de hipoglucemia al combinarse. Esta lista es parcial: el médico o farmacéutico revisa el conjunto de medicamentos y suplementos." ,
            forms = "La referencia describe tabletas orales con ambos componentes y concentraciones específicas. Compartir ingredientes con otros productos no demuestra equivalencia. La ficha pertenece a la Unión Europea y no acredita autorización ni disponibilidad en México." ,
            consult = "¿Qué función cumple cada componente? ¿Cuándo se revisarán los riñones y el hígado? ¿Qué cambios abdominales o de piel debemos comunicar? ¿Qué instrucciones debemos pedir antes de un estudio con contraste o una cirugía?" ,
            sources = listOf(
                DrugReference("EMA", "Eucreas · información del producto", "https://www.ema.europa.eu/en/documents/product-information/eucreas-epar-product-information_en.pdf", "EPAR revisión 27 · actualización 08/12/2025", reviewedOn = "22 de noviembre de 2026"),
            ),
            relatedQuestions = listOf(
                DrugRelatedQuestion("¿Qué hacen metformina y vildagliptina?", DrugIntent.MECHANISM),
                DrugRelatedQuestion("¿Por qué se revisan los riñones y el hígado?", DrugIntent.PRECAUTIONS),
                DrugRelatedQuestion("¿Qué precaución se describe con algunos medicamentos para la presión?", DrugIntent.INTERACTIONS),
            ),
            related = listOf("metformin_sitagliptin", "metformin_linagliptin"),
