        entry(
            id = "metformin_empagliflozin",
            name = "Metformina + empagliflozina",
            family = "Combinaciones orales",
            aliases = listOf("empagliflozina metformina", "metformina empagliflozina"),
            summary = "Biguanida e inhibidor SGLT2 en formulaciones inmediatas o prolongadas.",
            identify = "Esta tableta reúne metformina y empagliflozina, dos principios activos que actúan de manera distinta. La fuente estadounidense describe una presentación con metformina de liberación inmediata y otra llamada XR, en la que la metformina se libera de forma prolongada.\n\nSi el envase cambia, revisa el nombre completo y la identificación XR con el equipo o farmacéutico. Esta ficha se refiere a los productos de la fuente; no confirma autorización ni disponibilidad en México." ,
            purpose = "La ficha estadounidense contempla esta combinación para mejorar el control de la glucosa en diabetes tipo 2. También describe efectos de empagliflozina sobre ciertos riesgos cardiovasculares y renales en grupos concretos de adultos, dependiendo de sus enfermedades y características.\n\nEso no significa que el producto sea apropiado para todas las personas con diabetes o problemas renales. El equipo explica por qué se indicó y qué seguimiento requiere." ,
            mechanism = "El hígado libera glucosa a la sangre incluso entre comidas; la metformina ayuda principalmente a reducir su producción. La empagliflozina actúa en los riñones, donde bloquea una proteína llamada SGLT2 que normalmente devuelve parte de la glucosa filtrada a la sangre.\n\nAl bloquear esa proteína, una mayor cantidad de glucosa sale en la orina. Esto no indica por sí mismo si el tratamiento es suficiente ni permite interpretar las lecturas de una persona." ,
            effects = "La metformina puede acompañarse de diarrea, náuseas o molestias abdominales. La empagliflozina aumenta la salida de glucosa por la orina y la fuente describe infecciones urinarias y genitales; perder más líquido también puede favorecer mareo o presión baja. Comunica cambios persistentes al equipo: estos síntomas pueden tener otras causas.\n\nLa acidosis láctica y la cetoacidosis son acumulaciones peligrosas de ácidos que necesitan valoración urgente. La cetoacidosis puede presentarse aunque la glucosa no parezca muy elevada. Somnolencia intensa, dificultad para respirar, náuseas o dolor abdominal pueden ser señales y no permiten identificar la causa por sí solos. Dolor, enrojecimiento o hinchazón en genitales o periné junto con fiebre o malestar también requieren atención urgente por la posibilidad de una infección grave." ,
            contra = "La etiqueta consultada contraindica esta combinación cuando existe función renal gravemente reducida, acidosis metabólica —incluida la cetoacidosis— o hipersensibilidad a alguno de sus ingredientes. Una contraindicación es distinta de una precaución: otras circunstancias pueden requerir valoración y seguimiento por el equipo.\n\nLa función renal se estima con análisis que un profesional debe interpretar; la aplicación no determina si una persona puede utilizar el medicamento.",
            prec = "El equipo valora la función renal, la pérdida de líquidos, los cambios en los pies y la vitamina B12, entre otros aspectos. La edad avanzada y algunos diuréticos pueden aumentar la posibilidad de deshidratación o presión baja.\n\nUna enfermedad, ayuno, cirugía o estudio con contraste pueden requerir instrucciones específicas del equipo sobre este medicamento. Pregunta qué corresponde al caso y no suspendas ni reinicies por cuenta propia." ,
            inter = "Los diuréticos pueden aumentar la pérdida de líquidos. Cuando esta combinación se usa con insulina o una sulfonilurea, el riesgo de glucosa demasiado baja puede aumentar; el profesional decide cómo vigilarlo. Algunos medicamentos también pueden reducir la eliminación de metformina.\n\nEstos ejemplos no abarcan todas las interacciones. Lleva al equipo una lista de los productos recetados, suplementos y medicamentos sin receta." ,
            forms = "La fuente describe tabletas con metformina de liberación inmediata y tabletas XR de liberación prolongada. La palabra XR señala que la metformina se libera de otra manera; compartir ingredientes no convierte las dos presentaciones en intercambiables.\n\nLa etiqueta indica que la tableta XR de esta marca debe tragarse entera, sin partirla ni triturarla. Si existe dificultad para tragar o se recibe otro envase, pide orientación al equipo o farmacéutico antes de cambiar la forma de administrarla." ,
            consult = "¿La tableta es inmediata o XR y qué contiene? ¿Cómo se revisarán la función renal y la vitamina B12? ¿Qué señales urinarias o genitales debemos comunicar? ¿Qué instrucciones debemos pedir si hay enfermedad, cirugía o estudio con contraste?" ,
            sources = listOf(
                DrugReference("NLM · DailyMed", "SYNJARDY / SYNJARDY XR · ficha oficial", "https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=0fdd0255-0055-65f3-b2c0-db8fbb87beae", "Revisión 08/2026", reviewedOn = "22 de noviembre de 2026"),
            ),
