        entry(
            id = "metformin_glimepiride",
            name = "Metformina + glimepirida",
            family = "Combinaciones orales",
            aliases = listOf("glimepirida metformina", "metformina glimepirida"),
            summary = "Biguanida y sulfonilurea; se documenta la formulación prolongada de India.",
            identify = "La referencia de India describe una tableta de dos capas que combina glimepirida y metformina de liberación prolongada. Identificar ambos componentes ayuda a no confundirla con metformina sola." ,
            purpose = "El inserto de India describe esta combinación para diabetes tipo 2 cuando la alimentación, la actividad física y uno de sus componentes por separado no logran el control de glucosa buscado. La decisión sobre un tratamiento corresponde al equipo y no se deduce de esta descripción.\n\nLa tableta documentada tiene dos capas: una contiene glimepirida y la otra metformina de liberación prolongada. Conviene identificar ambos componentes y la presentación al revisar el envase. Este documento de India no acredita autorización, disponibilidad ni equivalencia de productos en México." ,
            mechanism = "La metformina ayuda principalmente a reducir la glucosa que produce el hígado, incluso entre comidas. La glimepirida, una sulfonilurea, estimula células del páncreas para que liberen insulina, hormona que ayuda a los tejidos a aprovechar la glucosa.\n\nAl aumentar la liberación de insulina puede producir hipoglucemia, una bajada excesiva de glucosa. La liberación prolongada describe una capa de metformina y no elimina ese riesgo." ,
            effects = "Pueden presentarse náusea, diarrea y otras molestias digestivas. La hipoglucemia puede acompañarse de sudoración, hambre, temblor o confusión; sus señales no siempre se reconocen fácilmente. Pregunta al equipo qué plan escrito corresponde.\n\nUna baja grave puede causar pérdida de conciencia o convulsiones y requiere atención urgente. La acidosis láctica es una acumulación grave de ácido asociada a metformina; debilidad intensa, somnolencia o dificultad para respirar también requieren atención urgente. Una reacción alérgica intensa requiere ayuda inmediata." ,
            contra = "El inserto incluye alergia a componentes o sulfonamidas, embarazo/lactancia, acidosis, insuficiencia renal grave o hepática, alcoholismo y estados agudos con deshidratación, shock o hipoxia; también contraste intravascular.",
            prec = "Las comidas irregulares o insuficientes, la función renal disminuida y la edad avanzada pueden influir en el riesgo de hipoglucemia. Los riñones participan en la eliminación de metformina, por lo que el equipo revisa su función.\n\nLa deficiencia de G6PD es una condición que afecta la protección de los glóbulos rojos y requiere valoración. Informa cambios de alimentación y pregunta qué hacer si se omite una comida o se olvida una administración; no ajustes el tratamiento por cuenta propia." ,
            inter = "Fluconazol y otros medicamentos pueden potenciar el efecto de glimepirida y aumentar el riesgo de glucosa baja. Los betabloqueadores pueden hacer menos evidentes algunas señales. El alcohol en exceso y medicamentos que alteran la función renal también requieren revisión por el componente de metformina.\n\nEl inserto describe además una interacción con colesevelam que reduce la absorción de glimepirida. Muestra al médico o farmacéutico todos los productos antes de cambiar horarios o tratamientos; la lista no es completa." ,
            forms = "El documento de India describe una tableta bicapa con metformina de liberación prolongada y señala que debe tragarse entera, sin triturar ni masticar. Si hay dificultad para tragarla, consulta al equipo.\n\nEsta fuente no acredita autorización, disponibilidad ni equivalencia de ninguna presentación en México." ,
            consult = "¿Qué contiene exactamente la tableta y cuál es su presentación? ¿Cómo reconocer una baja de glucosa y qué plan escrito debemos seguir? ¿Qué hacer si se omite una comida? ¿Cuándo se revisará la función renal y qué otros medicamentos requieren revisión?" ,
            sources = listOf(
                DrugReference("Sanofi India · fabricante", "Amaryl M · inserto para profesionales", "https://www.sanofi.com/assets/countries/india/docs/science-and-innovation/for-healthcare-professionals/product-information/pharmaceuticals/Amaryl-M_PI-_Dec-2025.pdf", "Diciembre 2025 · formulación de liberación prolongada de India", reviewedOn = "22 de noviembre de 2026"),
            ),
