        entry(
            id = "metformin_pioglitazone",
            name = "Metformina + pioglitazona",
            family = "Combinaciones orales",
            aliases = listOf("pioglitazona metformina", "metformina pioglitazona"),
            summary = "Biguanida y tiazolidinediona para diabetes tipo 2.",
            identify = "La tableta combina metformina, una biguanida, y pioglitazona, una tiazolidinediona. Contiene dos principios activos, de modo que las advertencias del producto incluyen las de ambos." ,
            purpose = "La ficha estadounidense describe esta combinación de metformina y pioglitazona para mejorar el control de glucosa en adultos con diabetes tipo 2, junto con las medidas de alimentación y actividad física acordadas con el equipo. Ambos componentes están en una tableta y deben identificarse al revisar el tratamiento completo.\n\nLa referencia no recomienda este producto para diabetes tipo 1 ni para tratar una cetoacidosis diabética, una complicación que necesita atención médica. La elección y seguimiento dependen de la valoración profesional; esta ficha no acredita disponibilidad en México." ,
            mechanism = "El hígado produce glucosa incluso entre comidas. La metformina ayuda principalmente a reducir esa producción. La pioglitazona actúa sobre un receptor llamado PPAR-gamma y ayuda a que ciertos tejidos respondan mejor a la insulina, hormona que facilita el aprovechamiento de la glucosa.\n\nSon mecanismos distintos reunidos en la misma tableta. Mejor respuesta a la insulina no significa que el medicamento sustituya automáticamente la insulina indicada ni que cualquiera de los componentes sea apropiado para todas las personas." ,
            effects = "La ficha describe hinchazón, aumento de peso, diarrea y dolor de cabeza. La pioglitazona puede favorecer la retención de líquidos; un aumento rápido de peso, hinchazón nueva o dificultad para respirar puede indicar empeoramiento del funcionamiento del corazón y debe comunicarse de inmediato.\n\nLa metformina se asocia en raras ocasiones con acidosis láctica, una acumulación grave de ácido que puede acompañarse de debilidad intensa, somnolencia o dificultad para respirar. Estos síntomas, la falta de aire importante o la piel y ojos amarillos necesitan valoración profesional urgente. No todas las personas experimentan estos efectos." ,
            contra = "La ficha contraindica iniciar esta combinación en insuficiencia cardiaca establecida de clase III o IV, una clasificación profesional de la limitación que provocan sus síntomas. También la contraindica ante función renal gravemente reducida, acidosis metabólica o alergia grave a sus componentes. No se recomienda en insuficiencia cardiaca sintomática según la ficha." ,
            prec = "El equipo revisa la función renal y hepática y puede considerar los niveles de vitamina B12 por la metformina. La pioglitazona requiere atención a la retención de líquidos, posibles fracturas y cambios de visión; informa antecedentes o síntomas que el equipo deba conocer.\n\nLa ficha advierte sobre cáncer de vejiga y edema macular, que es acumulación de líquido en la parte central de la retina. Esto no significa que el medicamento cause esos problemas en cada persona. Antes de un procedimiento o estudio con contraste, solicita instrucciones individuales." ,
            inter = "Gemfibrozilo puede aumentar la exposición a pioglitazona y rifampicina puede disminuirla. La combinación con insulina puede aumentar la retención de líquidos; el alcohol en exceso aumenta los riesgos asociados con metformina.\n\nEsta lista no cubre todas las interacciones. Lleva al médico o farmacéutico los nombres de productos recetados, de venta libre y suplementos para que valore las combinaciones." ,
            forms = "La fuente consultada describe tabletas orales de liberación inmediata que combinan ambos componentes. Confirma el nombre y la concentración del envase; no supongas equivalencia con otro producto o formulación solo porque contiene metformina." ,
            consult = "¿Qué aporta cada componente? ¿Qué aumento de peso, hinchazón o dificultad para respirar debemos comunicar inmediatamente? ¿Cómo se revisarán riñones, hígado y vitamina B12? ¿Hay antecedentes de fracturas, problemas de vejiga o visión que debamos comentar?" ,
            sources = listOf(
                DrugReference("NLM · DailyMed", "ACTOPLUS MET · ficha oficial", "https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=42e49120-6f3f-11db-9fe1-0800200c9a66", "Revisión 08/2026", reviewedOn = "22 de noviembre de 2026"),
            ),
            relatedQuestions = listOf(
                DrugRelatedQuestion("¿Cómo actúan metformina y pioglitazona?", DrugIntent.MECHANISM),
