        entry(
            id = "empagliflozin_linagliptin",
            name = "Empagliflozina + linagliptina",
            family = "Combinaciones orales",
            aliases = listOf("linagliptina empagliflozina", "empagliflozina linagliptina"),
            summary = "Combinación de inhibidores SGLT2 y DPP-4 para diabetes tipo 2.",
            identify = "Esta tableta reúne empagliflozina y linagliptina; no contiene metformina. Pertenecen a familias distintas y el nombre completo del producto ayuda a identificar ambos principios activos." ,
            purpose = "La ficha estadounidense describe la combinación para mejorar el control de glucosa en adultos con diabetes tipo 2. Distingue además un beneficio de empagliflozina sobre la muerte cardiovascular en adultos con diabetes tipo 2 y enfermedad cardiovascular establecida.\n\nEse dato no indica que este producto sea adecuado para todas las personas con diabetes ni permite elegir un tratamiento desde Bitavida." ,
            mechanism = "La empagliflozina bloquea SGLT2, una proteína de los riñones que normalmente devuelve parte de la glucosa filtrada a la sangre. Como resultado, aumenta la eliminación de glucosa en la orina.\n\nLa linagliptina actúa de otro modo: bloquea DPP-4, una enzima que descompone señales intestinales llamadas incretinas. Estas señales ayudan al páncreas a regular la liberación de insulina y glucagón según la glucosa. Son dos acciones diferentes en una tableta." ,
            effects = "La ficha describe infecciones urinarias, molestias de nariz y garganta e infecciones respiratorias altas. También puede haber pérdida de líquidos y mareo; comunica al equipo síntomas persistentes o que afecten las actividades.\n\nLa cetoacidosis es una acumulación peligrosa de ácidos y puede acompañarse de náuseas, dolor abdominal o dificultad respiratoria. Dolor abdominal intenso y persistente puede ser una señal de pancreatitis, inflamación del páncreas. Dolor, enrojecimiento o hinchazón genital o del periné junto con fiebre o malestar puede señalar una infección grave. Estos cambios requieren valoración urgente; no hace falta que aparezcan todos." ,
            contra = "Contraindicada en alergia a los componentes o sus excipientes.",
            prec = "La función renal y el estado de hidratación importan en la valoración antes y durante el tratamiento. Las personas mayores o que reciben algunos diuréticos pueden ser más susceptibles a presión baja por pérdida de líquidos. La ficha también pide comunicar infecciones o heridas nuevas en pies y piernas.\n\nInforma al equipo si hay antecedentes de inflamación del páncreas o insuficiencia cardiaca. Ante una enfermedad, cirugía o ayuno prolongado, solicita instrucciones específicas; no suspendas ni reinicies por cuenta propia." ,
            inter = "Los diuréticos pueden aumentar la pérdida de líquidos. La insulina o una sulfonilurea pueden aumentar el riesgo de glucosa demasiado baja al combinarse con este producto. La rifampicina puede disminuir la exposición a linagliptina.\n\nEsta lista es parcial; el equipo necesita conocer todos los medicamentos y suplementos para revisar el conjunto sin que la aplicación haga cambios." ,
            forms = "La referencia describe tabletas orales con dos principios activos. No es una tableta de metformina. Las restricciones renales de este producto no son idénticas a las de dapagliflozina con saxagliptina; no supongas que son intercambiables." ,
            consult = "¿Qué contiene exactamente mi tableta? ¿Cómo se revisarán los riñones y la hidratación? ¿Qué cambios urinarios, genitales o de los pies debemos comunicar? ¿Qué instrucciones debemos pedir para una cirugía o enfermedad?" ,
            sources = listOf(
                DrugReference("NLM · DailyMed", "GLYXAMBI · ficha oficial", "https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=ddbab689-f76c-488c-9613-4168d41dd730", "Revisión 01/2026", reviewedOn = "22 de noviembre de 2026"),
            ),
            relatedQuestions = listOf(
                DrugRelatedQuestion("¿Qué ingredientes contiene esta tableta?", DrugIntent.IDENTIFY),
                DrugRelatedQuestion("¿Cómo actúan empagliflozina y linagliptina?", DrugIntent.MECHANISM),
                DrugRelatedQuestion("¿Qué interacción se describe con rifampicina?", DrugIntent.INTERACTIONS),
            ),
            related = listOf("dapagliflozin_saxagliptin", "metformin_empagliflozin"),
