        entry(
            id = "dapagliflozin_saxagliptin",
            name = "Dapagliflozina + saxagliptina",
            family = "Combinaciones orales",
            aliases = listOf("saxagliptina dapagliflozina", "dapagliflozina saxagliptina"),
            summary = "Combinación de inhibidores SGLT2 y DPP-4 para diabetes tipo 2.",
            identify = "Esta tableta combina dapagliflozina y saxagliptina, dos principios activos de familias diferentes. No incluye metformina; revisar ambos nombres ayuda a distinguirla de otras combinaciones." ,
            purpose = "La ficha estadounidense describe este producto junto con alimentación y actividad física para mejorar el control de la glucosa en adultos con diabetes tipo 2. El equipo tratante decide si sus componentes son apropiados para cada persona; la ficha no permite iniciar ni cambiar un tratamiento." ,
            mechanism = "La dapagliflozina actúa en los riñones: bloquea una proteína llamada SGLT2 que devuelve parte de la glucosa filtrada a la sangre. Con ello aumenta la eliminación de glucosa en la orina.\n\nLa saxagliptina bloquea la enzima DPP-4, que descompone las incretinas, señales liberadas por el intestino después de comer. Al durar más esas señales ayudan al páncreas a regular insulina y glucagón. La ficha combina estos dos mecanismos, pero no los hace equivalentes a los componentes de otro producto." ,
            effects = "La ficha describe infecciones respiratorias altas, infecciones urinarias y cambios en grasas de la sangre. El profesional interpreta los análisis; la aplicación no puede deducir su significado individual.\n\nLa cetoacidosis es una acumulación peligrosa de ácidos que puede acompañarse de náuseas, dolor abdominal o dificultad para respirar. Dolor abdominal intenso y persistente puede ser una señal de pancreatitis, inflamación del páncreas. Dolor o hinchazón genital o del periné con fiebre o malestar puede señalar una infección grave. Estas situaciones requieren valoración urgente; comunícate también ante falta de aire o hinchazón nuevas, que el equipo necesita evaluar." ,
            contra = "Contraindicada ante alergia grave a los componentes, función renal moderada/grave reducida según la ficha, enfermedad renal terminal o diálisis.",
            prec = "La ficha contraindica esta formulación en ciertos grados de función renal reducida y en diálisis; el profesional interpreta la función renal y determina si la indicación corresponde. La edad avanzada y la pérdida de líquidos aumentan la posibilidad de presión baja.\n\nLos antecedentes de insuficiencia cardiaca o pancreatitis son datos relevantes para el equipo. Antes de una cirugía o ayuno prolongado solicita instrucciones específicas, sin ajustar el medicamento por cuenta propia." ,
            inter = "La ficha indica no combinar este producto con inhibidores potentes de CYP3A4/5, como ketoconazol, porque pueden aumentar la exposición a saxagliptina. Los diuréticos pueden aumentar la pérdida de líquidos; la insulina y las sulfonilureas pueden aumentar el riesgo de hipoglucemia.\n\nEstos ejemplos no son una lista completa. El médico o farmacéutico debe revisar todos los medicamentos y suplementos antes de cualquier modificación." ,
            forms = "La referencia corresponde a tabletas orales; indica tragarlas enteras sin triturar, partir ni masticar. Esta formulación no comparte todas las restricciones renales con otras combinaciones de familias parecidas. Consulta al equipo ante un cambio de envase o si hay dificultad para tragarla." ,
            consult = "¿Qué contienen las tabletas y cómo las identifico? ¿Cuándo se revisarán la función renal y la hidratación? ¿Qué cambios de respiración, hinchazón o dolor abdominal debo comunicar? ¿Los medicamentos actuales incluyen alguno que no deba combinarse con este producto?" ,
            sources = listOf(
                DrugReference("NLM · DailyMed", "QTERN · ficha oficial", "https://dailymed.nlm.nih.gov/dailymed/downloadpdffile.cfm?setId=423c489c-085b-4320-b892-7868ebd6dc6b", "Revisión 06/2026", reviewedOn = "22 de noviembre de 2026"),
            ),
            relatedQuestions = listOf(
                DrugRelatedQuestion("¿Qué ingredientes contiene esta tableta?", DrugIntent.IDENTIFY),
                DrugRelatedQuestion("¿Cómo actúan dapagliflozina y saxagliptina?", DrugIntent.MECHANISM),
                DrugRelatedQuestion("¿Qué interacción se describe con ketoconazol?", DrugIntent.INTERACTIONS),
            ),
