        entry(
            id = "losartan",
            name = "Losartán",
            family = "Cardiovasculares y renales",
            aliases = listOf("losartan potásico", "losartán potásico", "losartan potassium"),
            summary = "Antagonista de angiotensina II para indicaciones de presión y riñón; no es un hipoglucemiante.",
            identify = "Losartán pertenece a los antagonistas de receptores de angiotensina II, llamados ARA-II. Actúa sobre señales que intervienen en la presión arterial; no es un medicamento para bajar directamente la glucosa." ,
            purpose = "La ficha estadounidense lo contempla para tratar presión arterial alta. También describe su uso para una enfermedad renal en personas con diabetes tipo 2 que cumplen condiciones específicas, entre ellas hipertensión y proteínas en la orina.\n\nLa proteína en orina es un dato que el profesional interpreta junto con otros análisis. Esta guía no permite decidir si una persona necesita losartán ni deducir un diagnóstico por el medicamento que usa." ,
            mechanism = "El cuerpo produce angiotensina II, una señal que puede estrechar los vasos sanguíneos y favorecer la liberación de aldosterona, una hormona que participa en el equilibrio de sal y agua. Losartán bloquea un receptor por el que actúa esa señal, por lo que sus efectos sobre los vasos y la aldosterona disminuyen.\n\nLisinopril interviene en otro punto del mismo sistema: disminuye la formación de angiotensina II. Esa diferencia no significa que ambos medicamentos sean intercambiables o deban combinarse." ,
            effects = "En estudios de la ficha se notificaron mareo, congestión nasal, infección respiratoria alta y dolor de espalda. El mareo puede afectar la estabilidad y merece comunicación al equipo si persiste o causa caídas; no siempre se debe al medicamento.\n\nTambién pueden aparecer presión demasiado baja, cambios en la función renal o potasio alto, que el profesional evalúa con mediciones y análisis. La hinchazón de labios, lengua o garganta, especialmente con dificultad para respirar, requiere atención urgente." ,
            contra = "Contraindicado ante alergia a componentes y con aliskirén en personas con diabetes.",
            prec = "La pérdida importante de líquidos o sal puede favorecer una caída de presión. La ficha también advierte que la función renal puede cambiar y que el potasio en sangre puede elevarse, por lo que el equipo decide qué análisis y seguimiento necesita la persona.\n\nEl embarazo requiere comunicación inmediata con el equipo: los medicamentos de este sistema pueden dañar al feto. No modifiques una indicación por cuenta propia; pide instrucciones al profesional." ,
            inter = "Los suplementos y otros productos que elevan el potasio pueden aumentar su concentración en sangre. Algunos antiinflamatorios pueden afectar la función renal o reducir el efecto sobre la presión; el litio puede acumularse. Otros medicamentos que actúan sobre el mismo sistema requieren revisión por posibles riesgos.\n\nEsta lista es parcial. Comenta al profesional todos los medicamentos, productos sin receta y suplementos; no decidas suspenderlos a partir de esta ficha." ,
            forms = "La presentación consultada consiste en tabletas orales de losartán potásico. También pueden existir productos combinados: revisa el nombre completo del envase para distinguirlos de una tableta con un solo principio activo. La disponibilidad en México no está verificada por esta referencia." ,
            consult = "¿Qué objetivo tiene losartán en este caso: presión, riñón u otro? ¿Cuándo se revisarán función renal y potasio? ¿Qué debemos comunicar si hay mareo, pérdida de líquidos o cambios de medicamentos? ¿El envase contiene solo losartán o también otro producto?" ,
            sources = listOf(
                DrugReference("NLM · DailyMed", "COZAAR · ficha oficial", "https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9949448f-c3b9-44ee-94ed-c1aca8c90f39", "Revisión 06/2025", reviewedOn = "22 de noviembre de 2026"),
            ),
            relatedQuestions = listOf(
                DrugRelatedQuestion("¿Cómo actúa losartán sobre la angiotensina II?", DrugIntent.MECHANISM),
                DrugRelatedQuestion("¿Por qué el equipo revisa el potasio y los riñones?", DrugIntent.PRECAUTIONS),
                DrugRelatedQuestion("¿Qué productos pueden elevar el potasio?", DrugIntent.INTERACTIONS),
            ),
            related = listOf("lisinopril", "finerenone"),
        ),
        entry(
            id = "lisinopril",
            name = "Lisinopril",
            family = "Cardiovasculares y renales",
            aliases = listOf("lisinopril"),
            summary = "Inhibidor de la ECA utilizado en indicaciones cardiovasculares; no es un hipoglucemiante.",
            identify = "Lisinopril pertenece a los inhibidores de la enzima convertidora de angiotensina, llamados IECA. Se utiliza en determinadas condiciones de presión arterial y corazón; no es un tratamiento directo para reducir glucosa." ,
            purpose = "La ficha consultada incluye el tratamiento de la hipertensión y su uso como complemento en insuficiencia cardiaca. También contempla su uso en circunstancias específicas después de un infarto agudo. La insuficiencia cardiaca significa que el corazón no bombea como el cuerpo necesita; no significa necesariamente que se haya detenido.\n\nLa indicación concreta la explica el equipo tratante. Tener diabetes no significa por sí solo que una persona necesite lisinopril." ,
            mechanism = "Una enzima del cuerpo, llamada ECA, ayuda a formar angiotensina II. Esta sustancia estrecha los vasos y estimula la liberación de aldosterona, una hormona relacionada con el equilibrio de sal y agua. Lisinopril inhibe esa enzima y reduce la formación de angiotensina II.\n\nA diferencia de lisinopril, losartán bloquea un receptor de angiotensina II. Las fichas tienen advertencias y contraindicaciones propias; no deben considerarse productos equivalentes ni combinarse por decisión de la aplicación." ,
            effects = "Entre los efectos descritos están la tos, el mareo y el dolor de cabeza. Una tos persistente o un mareo que afecta las actividades conviene comunicarlos para que el profesional investigue su causa.\n\nEl medicamento también puede asociarse con cambios en la función renal o elevación del potasio. Una hinchazón repentina de labios, lengua o garganta, con o sin dificultad respiratoria, puede ser angioedema y requiere atención urgente. La aplicación no identifica la causa de un síntoma." ,
            contra = "Contraindicado ante ciertos antecedentes de angioedema o alergia; con aliskirén en diabetes y con inhibidores de neprilisina como sacubitrilo, incluidos los periodos de separación de la ficha.",
            prec = "La presión puede bajar demasiado, especialmente ante pérdida de líquidos o uso de ciertos diuréticos. La función renal y el potasio en sangre pueden cambiar y el equipo considera los análisis adecuados. Comunica mareos importantes, desmayo, enfermedad o dificultad para beber normalmente.\n\nEl embarazo debe comunicarse inmediatamente: la ficha advierte que este medicamento puede dañar al feto. Solicita al equipo instrucciones para la situación concreta sin ajustar medicamentos por cuenta propia." ,
            inter = "Los diuréticos pueden aumentar la posibilidad de presión baja; algunos antiinflamatorios pueden afectar la función renal o el efecto del medicamento. Los productos que elevan potasio y el litio también requieren revisión.\n\nLa ficha contraindica determinadas combinaciones, como con sacubitrilo, y establece un intervalo al cambiar entre ellas que debe gestionar el equipo. Esta lista es incompleta; muestra al profesional todos los medicamentos y suplementos antes de cualquier cambio." ,
            forms = "La ficha consultada corresponde a tabletas por vía oral. El nombre, la concentración y los demás componentes del envase ayudan a identificar el producto; existen presentaciones que pueden combinar otros medicamentos. Consulta al farmacéutico si cambia el envase, sin suponer equivalencia." ,
            consult = "¿Qué objetivo tiene lisinopril en este caso? ¿Qué tos o mareo debo comunicar? ¿Cuándo se revisarán los riñones y el potasio? ¿Debemos consultar antes de usar antiinflamatorios, suplementos o medicamentos nuevos?" ,
            sources = listOf(
                DrugReference("NLM · DailyMed", "LISINOPRIL · ficha oficial", "https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f2e09150-22f2-4028-b214-917d686200ad", "Revisión 08/2026", reviewedOn = "22 de noviembre de 2026"),
            ),
            relatedQuestions = listOf(
                DrugRelatedQuestion("¿Cómo actúa lisinopril sobre la angiotensina II?", DrugIntent.MECHANISM),
                DrugRelatedQuestion("¿Qué tos o mareo conviene comunicar al equipo?", DrugIntent.SIDE_EFFECTS),
                DrugRelatedQuestion("¿Por qué se revisan la función renal y el potasio?", DrugIntent.PRECAUTIONS),
