        entry(
            id = "atorvastatin",
            name = "Atorvastatina",
            family = "Cardiovasculares y renales",
            aliases = listOf("atorvastatin", "atorvastatina cálcica"),
            summary = "Estatina para colesterol y reducción de riesgo cardiovascular en poblaciones específicas.",
            identify = "La atorvastatina pertenece a las estatinas. Actúa sobre el colesterol y se utiliza en situaciones cardiovasculares concretas; no sustituye los medicamentos indicados para controlar la glucosa." ,
            purpose = "La ficha estadounidense describe su uso para reducir el colesterol LDL y para disminuir la probabilidad de ciertos eventos cardiovasculares, como infarto o accidente cerebrovascular, en grupos específicos de adultos. Uno de esos grupos incluye personas con diabetes tipo 2 y otros factores de riesgo.\n\nLa indicación depende de la evaluación del equipo y no significa que toda persona con diabetes deba recibir una estatina. Un análisis y los antecedentes ayudan al profesional a conversar sobre los objetivos individuales." ,
            mechanism = "El colesterol es una sustancia que el cuerpo necesita; el hígado fabrica parte de él. La atorvastatina bloquea una enzima que interviene en esa fabricación. Como respuesta, el hígado aumenta la retirada de partículas LDL de la sangre.\n\nLas LDL transportan colesterol y su cantidad forma parte de la información que el profesional considera junto con otros factores cardiovasculares. La medicina actúa de manera distinta a los tratamientos dirigidos a bajar glucosa." ,
            effects = "La referencia describe, entre otros efectos, diarrea, dolor en articulaciones o extremidades e infecciones de vías respiratorias altas. Una molestia puede tener muchas causas y no toda persona que toma el medicamento la presenta.\n\nEn ocasiones puede ocurrir daño muscular importante. Comunica pronto el dolor, la sensibilidad o debilidad muscular que no tengan explicación, sobre todo si aparecen con malestar o fiebre. Orina oscura, debilidad intensa, piel u ojos amarillos u otros síntomas importantes requieren valoración médica pronta. La aplicación no puede determinar su causa." ,
            contra = "Contraindicada en insuficiencia hepática aguda, cirrosis descompensada y alergia a componentes.",
            prec = "La ficha identifica como factores que aumentan el riesgo de daño muscular la edad de 65 años o más, la función renal reducida, el hipotiroidismo no controlado y el uso de algunos medicamentos. El equipo también puede considerar pruebas del hígado antes del tratamiento y posteriormente según la situación.\n\nInforma si existe enfermedad hepática o embarazo. Tener un factor no confirma una complicación; el profesional decide qué vigilancia corresponde." ,
            inter = "Algunos antivirales, antibióticos como la claritromicina, antifúngicos y ciclosporina pueden aumentar la exposición a atorvastatina y el riesgo muscular; también se advierte sobre cantidades importantes de toronja. La ficha describe además una interacción con digoxina.\n\nEstos son ejemplos, no una lista completa. Lleva al médico o farmacéutico los envases o una lista de todo lo que utiliza la persona, incluidos productos sin receta. No suspendas ni cambies tratamientos por la información de esta guía." ,
            forms = "La fuente documenta tabletas orales; no es una recomendación para cambiar entre estatinas.",
            consult = "¿Qué objetivo cardiovascular se busca con esta estatina? ¿Qué dolor o debilidad muscular debo comunicar y a quién? ¿Qué análisis del hígado y del colesterol se revisarán? ¿Hay antibióticos, otros productos o alimentos que debamos consultar antes de usar?" ,
            sources = listOf(
                DrugReference("NLM · DailyMed", "LIPITOR · ficha oficial", "https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=a60cc18b-0631-4cf0-b021-9f52224ece65", "Revisión 04/2024", reviewedOn = "22 de noviembre de 2026"),
            ),
            relatedQuestions = listOf(
                DrugRelatedQuestion("¿Cómo actúa la atorvastatina sobre el colesterol LDL?", DrugIntent.MECHANISM),
                DrugRelatedQuestion("¿Qué cambios musculares conviene comunicar?", DrugIntent.SIDE_EFFECTS),
                DrugRelatedQuestion("¿Por qué se revisan algunos antibióticos y la toronja?", DrugIntent.INTERACTIONS),
            ),
            related = listOf("losartan", "finerenone"),
        ),
